INSERT INTO `question_chapters` VALUES (1939698943482920962, 1939698943482920961, '1', 1, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `question_chapters` VALUES (2004641871798972417, 1, '13', 0, '2025-12-27 03:54:01', '2025-12-27 03:54:01');
