INSERT INTO `questions` VALUES (1939698943482920963, 1939698943482920961, 1939698943482920962, 'single', '关于MySQL数据库的描述，正确的是', '{\"A\": \"MySQL是一种非关系型数据库\", \"B\": \"MySQL主要用于存储非结构化数据\", \"C\": \"MySQL是一种关系型数据库管理系统\", \"D\": \"MySQL不支持事务处理\"}', '[[\"C\"]]', 'MySQL是一种关系型数据库管理系统，支持事务处理、关系模型等特性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943482920964, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种数据类型用于存储日期？', '{\"A\": \"INT\", \"B\": \"VARCHAR\", \"C\": \"DATE\", \"D\": \"TEXT\"}', '[[\"C\"]]', 'DATE数据类型用于存储日期，DATATIME用于存储日期和时间。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281089, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL的存储引擎InnoDB支持事务处理吗？', '{}', '[[\"true\"]]', 'InnoDB是MySQL的默认存储引擎，支持事务处理，具备ACID特性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281090, 1939698943482920961, 1939698943482920962, 'short', '数据库的完整性约束包括以下哪些类型？', '{}', '[[\"主键约束|唯一约束|外键约束|检查约束|非空约束|默认值约束\"]]', '数据库完整性约束用于确保数据的正确性和一致性，包括主键约束、唯一约束、外键约束、检查约束、非空约束和默认值约束。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281091, 1939698943482920961, 1939698943482920962, 'short', '如何提高MySQL数据库的查询性能？', '{}', '[[\"优化查询语句、使用索引、合理设计表结构、增加硬件资源。\"]]', '无', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281092, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL的视图，以下说法正确的是', '{\"A\": \"视图是一个虚拟表，不存储数据\", \"B\": \"视图可以提高数据的安全性\", \"C\": \"视图可以简化复杂的查询操作\", \"D\": \"视图可以用于数据的插入\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', '视图是一个虚拟表，不存储数据，可以提高数据的安全性，简化复杂的查询操作，也可以用于数据的插入、更新和删除操作。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281093, 1939698943482920961, 1939698943482920962, 'multiple', 'MySQL中的事务具有以下哪些特性？', '{\"A\": \"原子性\", \"B\": \"一致性\", \"C\": \"隔离性\", \"D\": \"持久性\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', '事务的ACID特性包括原子性、一致性、隔离性和持久性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281094, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种锁用于防止其他事务对数据的修改？', '{\"A\": \"共享锁\", \"B\": \"排它锁\", \"C\": \"意向锁\", \"D\": \"读锁\"}', '[[\"B\"]]', '排它锁（X锁）用于防止其他事务对数据的修改。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281095, 1939698943482920961, 1939698943482920962, 'multiple', 'MySQL的权限管理包括以下哪些操作？', '{\"A\": \"授予权限\", \"B\": \"撤销权限\", \"C\": \"修改用户信息\", \"D\": \"删除用户\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', 'MySQL的权限管理包括授予权限、撤销权限、修改用户信息和删除用户。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281096, 1939698943482920961, 1939698943482920962, 'fill', '数据库备份的主要目的是什么？', '{}', '[[\"灾难恢复\"]]', '备份的主要目的是灾难恢复，确保数据在丢失或损坏时能够恢复。', 1, 0, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943512281097, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种日志文件用于记录数据库的运行情况和用户操作？', '{\"A\": \"二进制日志\", \"B\": \"错误日志\", \"C\": \"通用查询日志\", \"D\": \"慢查询日志\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', 'MySQL的日志文件包括二进制日志、错误日志、通用查询日志和慢查询日志，用于记录数据库的运行情况和用户操作。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641217, 1939698943482920961, 1939698943482920962, 'multiple', '数据库的故障类型包括以下哪些？', '{\"A\": \"事务故障\", \"B\": \"系统故障\", \"C\": \"介质故障\", \"D\": \"网络故障\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '数据库的故障类型包括事务故障、系统故障和介质故障。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641218, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种索引类型不允许有重复值？', '{\"A\": \"普通索引\", \"B\": \"唯一性索引\", \"C\": \"全文索引\", \"D\": \"空间索引\"}', '[[\"B\"]]', '唯一性索引不允许有重复值，而普通索引、全文索引和空间索引可以有重复值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641219, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的触发器，以下说法正确的是', '{\"A\": \"触发器是一种特殊的存储过程\", \"B\": \"触发器可以在数据插入\", \"C\": \"触发器可以用于实现数据完整性约束\", \"D\": \"触发器需要显式调用才能执行\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行，用于实现数据完整性约束。触发器不需要显式调用，而是由数据库系统自动触发。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641220, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种事务隔离级别可以防止“不可重复读”问题？', '{\"A\": \"READUNCOMMITTED\", \"B\": \"READCOMMITTED\", \"C\": \"REPEATABLEREAD\", \"D\": \"SERIALIZABLE\"}', '[[\"C\"], [\"D\"]]', 'REPEATABLEREAD和SERIALIZABLE隔离级别可以防止“不可重复读”问题。REPEATABLEREAD是MySQL的默认隔离级别。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641221, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种数据类型用于存储整数？', '{\"A\": \"INT\", \"B\": \"VARCHAR\", \"C\": \"DATE\", \"D\": \"TEXT\"}', '[[\"A\"]]', 'INT数据类型用于存储整数。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641222, 1939698943482920961, 1939698943482920962, 'multiple', '关于数据库的备份策略，以下说法正确的是', '{\"A\": \"定期备份数据库可以减少数据丢失的风险\", \"B\": \"备份应该在系统负载最低的时候进行\", \"C\": \"备份文件应该存储在与数据库服务器相同的磁盘上\", \"D\": \"备份文件应该定期测试以确保其可用性\"}', '[[\"A\"], [\"B\"], [\"D\"]]', '定期备份数据库可以减少数据丢失的风险，备份应该在系统负载最低的时候进行，备份文件应该存储在与数据库服务器不同的磁盘上以防止硬件故障导致数据丢失，备份文件应该定期测试以确保其可用性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641223, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种日志文件用于数据库恢复的日志操作？', '{\"A\": \"二进制日志\", \"B\": \"错误日志\", \"C\": \"通用查询日志\", \"D\": \"重做日志\"}', '[[\"D\"]]', '重做日志（REDO日志）用于记录事务的变更操作，以便在系统故障后恢复数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641224, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的存储过程，以下说法正确的是', '{\"A\": \"存储过程可以提高代码的重用性\", \"B\": \"存储过程可以减少网络通信流量\", \"C\": \"存储过程可以增强数据的安全性\", \"D\": \"存储过程可以用于模块化编程\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', '存储过程可以提高代码的重用性、减少网络通信流量、增强数据的安全性，并且可以用于模块化编程。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641225, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种锁用于防止其他事务对数据的读取？', '{\"A\": \"共享锁\", \"B\": \"排它锁\", \"C\": \"意向锁\", \"D\": \"读锁\"}', '[[\"B\"]]', '排它锁（X锁）用于防止其他事务对数据的读取和修改。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641226, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种日志文件用于记录错误信息？', '{\"A\": \"二进制日志\", \"B\": \"错误日志\", \"C\": \"通用查询日志\", \"D\": \"慢查询日志\"}', '[[\"B\"]]', '错误日志用于记录MySQL服务器的错误信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641227, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种数据类型用于存储固定长度的字符串？', '{\"A\": \"VARCHAR\", \"B\": \"CHAR\", \"C\": \"TEXT\", \"D\": \"BLOB\"}', '[[\"B\"]]', 'CHAR数据类型用于存储固定长度的字符串，VARCHAR用于存储可变长度的字符串。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641228, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的外键约束，以下说法正确的是', '{\"A\": \"外键约束用于建立两个表之间的关联关系\", \"B\": \"外键约束可以防止引用不存在的记录\", \"C\": \"外键约束可以用于级联更新和删除操作\", \"D\": \"外键约束必须引用主键\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '外键约束用于建立两个表之间的关联关系，可以防止引用不存在的记录，也可以用于级联更新和删除操作。外键约束通常引用主键，但也可以引用唯一键。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641229, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种运算符用于模糊查询？', '{\"A\": \"IN\", \"B\": \"LIKE\", \"C\": \"BETWEEN\", \"D\": \"ISNULL\"}', '[[\"B\"]]', 'LIKE运算符用于模糊查询，支持通配符“%”和“_”。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641230, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的聚合函数，以下说法正确的是', '{\"A\": \"COUNT(*)用于统计记录的总数\", \"B\": \"SUM()用于计算数值列的总和\", \"C\": \"AVG()用于计算数值列的平均值\", \"D\": \"MAX()和MIN()用于计算数值列的最大值和最小值\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', 'COUNT(*)用于统计记录的总数，SUM()用于计算数值列的总和，AVG()用于计算数值列的平均值，MAX()和MIN()用于计算数值列的最大值和最小值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641231, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于删除表中的所有记录？', '{\"A\": \"DELETE FROM表名\", \"B\": \"TRUNCATETABLE表名\", \"C\": \"DROP TABLE表名\", \"D\": \"ALTER TABLE表名\"}', '[[\"A\"], [\"B\"]]', 'DELETE FROM表名用于删除表中的所有记录，TRUNCATETABLE表名也可以删除表中的所有记录，但TRUNCATE是DDL操作，效率更高。DROP TABLE表名用于删除整个表，ALTER TABLE表名用于修改表结构。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943541641232, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的事务控制语句，以下说法正确的是', '{\"A\": \"COMMIT用于提交事务\", \"B\": \"ROLLBACK用于回滚事务\", \"C\": \"STARTTRANSACTION用于开始一个新事务\", \"D\": \"SAVEPOINT用于设置事务的保存点\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', 'COMMIT用于提交事务，ROLLBACK用于回滚事务，STARTTRANSACTION用于开始一个新事务，SAVEPOINT用于设置事务的保存点。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001346, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种存储引擎支持全文索引？', '{\"A\": \"InnoDB\", \"B\": \"MyISAM\", \"C\": \"MEMORY\", \"D\": \"ARCHIVE\"}', '[[\"B\"]]', 'MyISAM存储引擎支持全文索引，InnoDB在MySQL5.6及以上版本也支持全文索引。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001347, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于修改表结构？', '{\"A\": \"CREATE TABLE\", \"B\": \"ALTER TABLE\", \"C\": \"DROP TABLE\", \"D\": \"TRUNCATETABLE\"}', '[[\"B\"]]', 'ALTER TABLE用于修改表结构，CREATE TABLE用于创建表，DROP TABLE用于删除表，TRUNCATETABLE用于删除表中的所有记录。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001348, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于创建索引？', '{\"A\": \"CREATE INDEX\", \"B\": \"ALTER TABLEADDINDEX\", \"C\": \"CREATE TABLE\", \"D\": \"DROP INDEX\"}', '[[\"A\"], [\"B\"]]', 'CREATE INDEX和ALTER TABLEADDINDEX都可以用于创建索引，CREATE TABLE用于创建表，DROP INDEX用于删除索引。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001349, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的触发器，以下说法正确的是', '{\"A\": \"触发器是一种特殊的存储过程\", \"B\": \"触发器可以在数据插入\", \"C\": \"触发器可以用于实现数据完整性约束\", \"D\": \"触发器需要显式调用才能执行\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行，用于实现数据完整性约束。触发器不需要显式调用，而是由数据库系统自动触发。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001350, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于删除索引？', '{\"A\": \"DROP INDEX\", \"B\": \"ALTER TABLEDROP INDEX\", \"C\": \"DELETE INDEX\", \"D\": \"TRUNCATEINDEX\"}', '[[\"A\"], [\"B\"]]', 'DROP INDEX和ALTER TABLEDROP INDEX都可以用于删除索引，DELETE INDEX和TRUNCATEINDEX不是有效的MySQL语句。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001351, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于创建视图？', '{\"A\": \"CREATE VIEW\", \"B\": \"ALTER VIEW\", \"C\": \"DROP VIEW\", \"D\": \"CREATE TABLE\"}', '[[\"A\"]]', 'CREATE VIEW用于创建视图，ALTER VIEW用于修改视图，DROP VIEW用于删除视图，CREATE TABLE用于创建表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001352, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种数据类型用于存储大文本数据？', '{\"A\": \"VARCHAR\", \"B\": \"TEXT\", \"C\": \"CHAR\", \"D\": \"INT\"}', '[[\"B\"]]', 'TEXT数据类型用于存储大文本数据，VARCHAR和CHAR用于存储较短的字符串，INT用于存储整数。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001353, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的存储过程，以下说法正确的是', '{\"A\": \"存储过程可以包含多个SQL语句\", \"B\": \"存储过程可以有输入参数和输出参数\", \"C\": \"存储过程可以提高代码的重用性\", \"D\": \"存储过程必须返回一个值\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '存储过程可以包含多个SQL语句，可以有输入参数和输出参数，可以提高代码的重用性。存储过程可以没有返回值，也可以有多个返回值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001354, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于删除用户？', '{\"A\": \"DROP USER\", \"B\": \"DELETE USER\", \"C\": \"REVOKE USER\", \"D\": \"ALTER USER\"}', '[[\"A\"]]', 'DROP USER用于删除用户，DELETE USER不是有效的MySQL语句，REVOKE用于撤销用户权限，ALTER USER用于修改用户信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001355, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于创建存储过程？', '{\"A\": \"CREATE PROCEDURE\", \"B\": \"CREATE FUNCTION\", \"C\": \"CREATE TRIGGER\", \"D\": \"CREATE VIEW\"}', '[[\"A\"]]', 'CREATE PROCEDURE用于创建存储过程，CREATE FUNCTION用于创建函数，CREATE TRIGGER用于创建触发器，CREATE VIEW用于创建视图。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001356, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于修改用户密码？', '{\"A\": \"ALTER USER\", \"B\": \"SETPASSWORD\", \"C\": \"UPDATEUSER\", \"D\": \"GRANTPASSWORD\"}', '[[\"A\"], [\"B\"]]', 'ALTER USER和SETPASSWORD都可以用于修改用户密码。UPDATEUSER不是有效的MySQL语句，GRANT用于授予权限。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943571001357, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的触发器，以下说法正确的是', '{\"A\": \"触发器是一种特殊的存储过程\", \"B\": \"触发器可以在数据插入\", \"C\": \"触发器可以用于实现数据完整性约束\", \"D\": \"触发器需要显式调用才能执行\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行，用于实现数据完整性约束。触发器不需要显式调用，而是由数据库系统自动触发。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361474, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于创建触发器？', '{\"A\": \"CREATE TRIGGER\", \"B\": \"CREATE PROCEDURE\", \"C\": \"CREATE FUNCTION\", \"D\": \"CREATE VIEW\"}', '[[\"A\"]]', 'CREATE TRIGGER用于创建触发器，CREATE PROCEDURE用于创建存储过程，CREATE FUNCTION用于创建函数，CREATE VIEW用于创建视图。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361475, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于创建表？', '{\"A\": \"CREATE TABLE\", \"B\": \"ALTER TABLE\", \"C\": \"DROP TABLE\", \"D\": \"TRUNCATETABLE\"}', '[[\"A\"]]', 'CREATE TABLE用于创建表，ALTER TABLE用于修改表结构，DROP TABLE用于删除表，TRUNCATETABLE用于删除表中的所有记录。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361476, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于删除视图？', '{\"A\": \"DROP VIEW\", \"B\": \"ALTER VIEW\", \"C\": \"CREATE VIEW\", \"D\": \"DELETE VIEW\"}', '[[\"A\"]]', 'DROP VIEW用于删除视图，ALTER VIEW用于修改视图，CREATE VIEW用于创建视图，DELETE VIEW不是有效的MySQL语句。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361477, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于创建用户？', '{\"A\": \"CREATE USER\", \"B\": \"ALTER USER\", \"C\": \"DROP USER\", \"D\": \"GRANTUSER\"}', '[[\"A\"]]', 'CREATE USER用于创建用户，ALTER USER用于修改用户信息，DROP USER用于删除用户，GRANT用于授予权限。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361478, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于授予权限？', '{\"A\": \"GRANT\", \"B\": \"REVOKE\", \"C\": \"ALTER USER\", \"D\": \"CREATE USER\"}', '[[\"A\"]]', 'GRANT语句用于授予权限，REVOKE用于撤销权限，ALTER USER用于修改用户信息，CREATE USER用于创建用户。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361479, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于撤销权限？', '{\"A\": \"GRANT\", \"B\": \"REVOKE\", \"C\": \"ALTER USER\", \"D\": \"DROP USER\"}', '[[\"B\"]]', 'REVOKE语句用于撤销权限，GRANT用于授予权限，ALTER USER用于修改用户信息，DROP USER用于删除用户。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361480, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的存储过程，以下说法正确的是', '{\"A\": \"存储过程可以包含多个SQL语句\", \"B\": \"存储过程可以有输入参数和输出参数\", \"C\": \"存储过程可以提高代码的重用性\", \"D\": \"存储过程必须返回一个值\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '存储过程可以包含多个SQL语句，可以有输入参数和输出参数，可以提高代码的重用性。存储过程可以没有返回值，也可以有多个返回值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361481, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于查看表结构？', '{\"A\": \"DESCRIBE\", \"B\": \"SHOW TABLES\", \"C\": \"SHOW COLUMNS\", \"D\": \"SHOW STATUS\"}', '[[\"A\"], [\"C\"]]', 'DESCRIBE和SHOW COLUMNS都可以用于查看表结构。SHOW TABLES用于列出数据库中的所有表，SHOW STATUS用于查看服务器状态。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361482, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的用户？', '{\"A\": \"SHOW USERS\", \"B\": \"SHOW GRANTS\", \"C\": \"SHOW DATABASES\", \"D\": \"SHOW TABLES\"}', '[[\"B\"]]', 'SHOW GRANTS用于查看当前用户的权限，SHOW USERS不是有效的MySQL语句，SHOW DATABASES用于列出所有数据库，SHOW TABLES用于列出当前数据库中的所有表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361483, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前用户的权限？', '{\"A\": \"SHOW GRANTS\", \"B\": \"SHOW PRIVILEGES\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW USERS\"}', '[[\"A\"]]', 'SHOW GRANTS用于查看当前用户的权限，SHOW PRIVILEGES不是有效的MySQL语句，SHOW STATUS用于查看服务器状态，SHOW USERS不是有效的MySQL语句。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361484, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的表？', '{\"A\": \"SHOW TABLES\", \"B\": \"SHOW DATABASES\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW GRANTS\"}', '[[\"A\"]]', 'SHOW TABLES用于查看当前数据库的表，SHOW DATABASES用于列出所有数据库，SHOW STATUS用于查看服务器状态，SHOW GRANTS用于查看当前用户的权限。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361485, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的存储过程？', '{\"A\": \"SHOW PROCEDURES\", \"B\": \"SHOW FUNCTIONS\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW CREATE PROCEDURE\"}', '[[\"A\"]]', 'SHOW PROCEDURES用于查看当前数据库的存储过程，SHOW FUNCTIONS用于查看当前数据库的函数，SHOW STATUS用于查看服务器状态，SHOW CREATE PROCEDURE用于查看存储过程的定义。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361486, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的触发器？', '{\"A\": \"SHOW TRIGGERS\", \"B\": \"SHOW STATUS\", \"C\": \"SHOW CREATE TRIGGER\", \"D\": \"SHOW TABLES\"}', '[[\"A\"]]', 'SHOW TRIGGERS用于查看当前数据库的触发器，SHOW STATUS用于查看服务器状态，SHOW CREATE TRIGGER用于查看触发器的定义，SHOW TABLES用于查看当前数据库的表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943600361487, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前会话的变量值？', '{\"A\": \"SHOW VARIABLES\", \"B\": \"SHOW SESSION VARIABLES\", \"C\": \"SHOW GLOBAL VARIABLES\", \"D\": \"SHOW STATUS\"}', '[[\"B\"]]', 'SHOW SESSION VARIABLES用于查看当前会话的变量值，SHOW GLOBALVARIABLES用于查看全局变量值，SHOW VARIABLES是SHOW SESSION VARIABLES的简写，SHOW STATUS用于查看服务器状态。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721602, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的存储过程，以下说法正确的是', '{\"A\": \"存储过程可以包含多个SQL语句\", \"B\": \"存储过程可以有输入参数和输出参数\", \"C\": \"存储过程可以提高代码的重用性\", \"D\": \"存储过程必须返回一个值\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '存储过程可以包含多个SQL语句，可以有输入参数和输出参数，可以提高代码的重用性。存储过程可以没有返回值，也可以有多个返回值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721603, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的函数？', '{\"A\": \"SHOW FUNCTIONS\", \"B\": \"SHOW PROCEDURES\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW CREATE FUNCTION\"}', '[[\"A\"]]', 'SHOW FUNCTIONS用于查看当前数据库的函数，SHOW PROCEDURES用于查看当前数据库的存储过程，SHOW STATUS用于查看服务器状态，SHOW CREATE FUNCTION用于查看函数的定义。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721604, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的事务隔离级别，以下说法正确的是', '{\"A\": \"READUNCOMMITTED允许读取未提交的事务数据\", \"B\": \"READCOMMITTED允许读取已提交的事务数据\", \"C\": \"REPEATABLEREAD可以防止不可重复读问题\", \"D\": \"SERIALIZABLE是最严格的隔离级别\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', 'READUNCOMMITTED允许读取未提交的事务数据，READCOMMITTED允许读取已提交的事务数据，REPEATABLEREAD可以防止不可重复读问题，SERIALIZABLE是最严格的隔离级别。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721605, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的存储引擎？', '{\"A\": \"SHOW ENGINES\", \"B\": \"SHOW STATUS\", \"C\": \"SHOW VARIABLES\", \"D\": \"SHOW TABLES\"}', '[[\"A\"]]', 'SHOW ENGINES用于查看当前数据库支持的存储引擎及其状态，SHOW STATUS用于查看服务器状态，SHOW VARIABLES用于查看系统变量，SHOW TABLES用于查看当前数据库的表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721606, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的视图，以下说法正确的是', '{\"A\": \"视图可以简化复杂的查询操作\", \"B\": \"视图可以提供数据的安全性保证\", \"C\": \"视图可以实现数据的逻辑独立性\", \"D\": \"视图可以存储数据\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '视图可以简化复杂的查询操作，提供数据的安全性保证，实现数据的逻辑独立性。视图是一个虚拟表，不存储数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721607, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的字符集？', '{\"A\": \"SHOW CHARACTER SET\", \"B\": \"SHOW COLLATION\", \"C\": \"SHOW VARIABLES\", \"D\": \"SHOW STATUS\"}', '[[\"A\"]]', 'SHOW CHARACTER SET用于查看当前数据库支持的字符集，SHOW COLLATION用于查看字符校对规则，SHOW VARIABLES用于查看系统变量，SHOW STATUS用于查看服务器状态。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721608, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的触发器定义？', '{\"A\": \"SHOW TRIGGERS\", \"B\": \"SHOW CREATE TRIGGER\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW TABLES\"}', '[[\"B\"]]', 'SHOW CREATE TRIGGER用于查看触发器的定义，SHOW TRIGGERS用于列出当前数据库的所有触发器，SHOW STATUS用于查看服务器状态，SHOW TABLES用于查看当前数据库的表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721609, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的索引，以下说法正确的是', '{\"A\": \"索引可以提高数据查询的效率\", \"B\": \"索引会占用额外的存储空间\", \"C\": \"索引会降低数据插入\", \"D\": \"索引越多越好\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '索引可以提高查询效率，但会占用额外的存储空间，并且在数据插入、更新和删除时需要维护索引，从而降低操作速度。索引数量并不是越多越好，需要合理设计。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721610, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的函数定义？', '{\"A\": \"SHOW FUNCTIONS\", \"B\": \"SHOW CREATE FUNCTION\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW TABLES\"}', '[[\"B\"]]', 'SHOW CREATE FUNCTION用于查看函数的定义，SHOW FUNCTIONS用于列出当前数据库的所有函数，SHOW STATUS用于查看服务器状态，SHOW TABLES用于查看当前数据库的表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721611, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于查看当前数据库的表结构？', '{\"A\": \"SHOW CREATE TABLE\", \"B\": \"DESCRIBE\", \"C\": \"SHOW TABLES\", \"D\": \"SHOW COLUMNS\"}', '[[\"A\"], [\"B\"]]', 'SHOW CREATE TABLE和DESCRIBE都可以用于查看表的结构。SHOW TABLES用于列出当前数据库的所有表，SHOW COLUMNS用于查看表的列信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721612, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的事务，以下说法正确的是', '{\"A\": \"事务必须满足ACID特性\", \"B\": \"事务可以包含多个SQL语句\", \"C\": \"事务可以被提交或回滚\", \"D\": \"事务的持久性意味着事务完成后，其对数据的影响是永久的\"}', '[[\"A\"], [\"B\"], [\"C\"], [\"D\"]]', '事务必须满足ACID特性，可以包含多个SQL语句，可以被提交或回滚，事务的持久性意味着事务完成后，其对数据的影响是永久的。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721613, 1939698943482920961, 1939698943482920962, 'multiple', '在MySQL中，以下哪种语句用于查看当前数据库的索引？', '{\"A\": \"SHOW INDEX\", \"B\": \"SHOW KEYS\", \"C\": \"SHOW TABLES\", \"D\": \"SHOW COLUMNS\"}', '[[\"A\"], [\"B\"]]', 'SHOW INDEX和SHOW KEYS都可以用于查看表的索引信息。SHOW TABLES用于列出当前数据库的所有表，SHOW COLUMNS用于查看表的列信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721614, 1939698943482920961, 1939698943482920962, 'multiple', '关于MySQL中的存储过程，以下说法正确的是', '{\"A\": \"存储过程可以包含多个SQL语句\", \"B\": \"存储过程可以有输入参数和输出参数\", \"C\": \"存储过程可以提高代码的重用性\", \"D\": \"存储过程必须返回一个值\"}', '[[\"A\"], [\"B\"], [\"C\"]]', '存储过程可以包含多个SQL语句，可以有输入参数和输出参数，可以提高代码的重用性。存储过程可以没有返回值，也可以有多个返回值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721615, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的触发器？', '{\"A\": \"SHOW TRIGGERS\", \"B\": \"SHOW CREATE TRIGGER\", \"C\": \"SHOW TABLES\", \"D\": \"SHOW STATUS\"}', '[[\"A\"]]', 'SHOW TRIGGERS用于列出当前数据库的所有触发器。SHOW CREATE TRIGGER用于查看触发器的定义，SHOW TABLES用于列出当前数据库的所有表，SHOW STATUS用于查看服务器状态。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721616, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的视图定义？', '{\"A\": \"SHOW CREATE VIEW\", \"B\": \"SHOW VIEWS\", \"C\": \"SHOW TABLES\", \"D\": \"SHOW STATUS\"}', '[[\"A\"]]', 'SHOW CREATE VIEW用于查看视图的定义。SHOW VIEWS不是有效的MySQL语句，SHOW TABLES用于列出当前数据库的所有表（视图也是表的一种），SHOW STATUS用于查看服务器状态。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721617, 1939698943482920961, 1939698943482920962, 'single', '在MySQL中，以下哪种语句用于查看当前数据库的存储过程定义？', '{\"A\": \"SHOW PROCEDURES\", \"B\": \"SHOW CREATE PROCEDURE\", \"C\": \"SHOW STATUS\", \"D\": \"SHOW TABLES\"}', '[[\"B\"]]', 'SHOW CREATE PROCEDURE用于查看存储过程的定义。SHOW PROCEDURES用于列出当前数据库的所有存储过程，SHOW STATUS用于查看服务器状态，SHOW TABLES用于列出当前数据库的所有表。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943629721618, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL是一种关系型数据库管理系统，支持事务处理、关系模型等特性。', '{}', '[[\"true\"]]', 'MySQL是一种关系型数据库管理系统，支持事务处理、关系模型等特性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943659081729, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，普通索引允许有重复值和空值（NULL）。', '{}', '[[\"true\"]]', '普通索引是MySQL的基本索引类型，可以创建在任何数据类型的列上，作为索引的列允许有重复值和空值（NULL）。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943663276034, 1939698943482920961, 1939698943482920962, 'judge', 'InnoDB存储引擎支持事务处理，具备ACID特性。', '{}', '[[\"true\"]]', 'InnoDB是MySQL的默认存储引擎，支持事务处理，具备原子性（A）、一致性（C）、隔离性（I）和持久性（D）等ACID特性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943663276035, 1939698943482920961, 1939698943482920962, 'judge', '视图是一个虚拟表，不存储数据，但可以用于数据的插入、更新和删除操作。', '{}', '[[\"true\"]]', '视图是一个虚拟表，不存储数据，但可以通过视图对基表进行插入、更新和删除操作，不过这些操作会受到某些限制。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470337, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，唯一性索引的列值必须是唯一的，但允许有空值。', '{}', '[[\"true\"]]', '唯一性索引的列值必须是唯一的，但允许有空值。主键索引是一种特殊的唯一性索引，不允许有空值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470338, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务必须满足ACID特性，即原子性、一致性、隔离性和持久性。', '{}', '[[\"true\"]]', '事务必须满足ACID特性，即原子性（Atomicity）、一致性（Consistency）、隔离性（Isolation）和持久性（Durability）。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470339, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，全文索引只能创建在CHAR、VARCHAR和TEXT类型的字段上。', '{}', '[[\"true\"]]', '全文索引只能创建在CHAR、VARCHAR和TEXT类型的字段上，用于提高查询字符串数据的效率。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470340, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的存储过程可以包含多个SQL语句，并且可以有输入参数和输出参数。', '{}', '[[\"true\"]]', '存储过程可以包含多个SQL语句，并且可以有输入参数（IN）、输出参数（OUT）和输入输出参数（INOUT）。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470341, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行。', '{}', '[[\"true\"]]', '触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行，用于实现数据完整性约束或其他特殊任务。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470342, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，SERIALIZABLE是最严格的隔离级别。', '{}', '[[\"true\"]]', 'SERIALIZABLE是最严格的隔离级别，可以防止所有并发事务问题，包括丢失更新、读脏数据、不可重复读和幻影读。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470343, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW TABLES语句可以查看当前数据库的所有表，包括视图。', '{}', '[[\"true\"]]', 'SHOW TABLES语句可以列出当前数据库的所有表，包括视图。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470344, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的索引可以提高查询效率，但会占用额外的存储空间，并且在数据插入、更新和删除时需要维护索引。', '{}', '[[\"true\"]]', '索引可以提高查询效率，但会占用额外的存储空间，并且在数据插入、更新和删除时需要维护索引，从而降低操作速度。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470345, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW CREATE TABLE语句可以查看表的结构定义。', '{}', '[[\"true\"]]', 'SHOW CREATE TABLE语句可以查看表的结构定义，包括表的创建语句和存储引擎等信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470346, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的视图可以隐藏数据的逻辑复杂性，并简化查询语句。', '{}', '[[\"true\"]]', '视图可以隐藏数据的逻辑复杂性，并简化查询语句，使用户可以更方便地访问数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470347, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW VARIABLES语句可以查看当前会话的变量值。', '{}', '[[\"true\"]]', 'SHOW VARIABLES语句可以查看当前会话的变量值，也可以查看全局变量值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470348, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，READUNCOMMITTED允许读取未提交的事务数据。', '{}', '[[\"true\"]]', 'READUNCOMMITTED是最低的隔离级别，允许读取未提交的事务数据，可能会导致读脏数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943667470349, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW STATUS语句可以查看服务器的状态信息。', '{}', '[[\"true\"]]', 'SHOW STATUS语句可以查看服务器的状态信息，包括连接数、运行时间、慢查询次数等。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943688441857, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的存储过程可以提高代码的重用性，并减少网络通信流量。', '{}', '[[\"true\"]]', '存储过程可以提高代码的重用性，并减少网络通信流量，因为存储过程在服务器端执行，减少了客户端和服务器之间的SQL语句传输，从而提高了效率。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943688441858, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW ENGINES语句可以查看当前数据库支持的存储引擎及其状态。', '{}', '[[\"true\"]]', 'SHOW ENGINES语句可以查看当前数据库支持的存储引擎及其状态，包括InnoDB、MyISAM等。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943688441859, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，REPEATABLEREAD可以防止不可重复读问题。', '{}', '[[\"true\"]]', 'REPEATABLEREAD隔离级别可以防止不可重复读问题，确保在同一个事务中多次读取同一数据时，结果是一致的。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
