INSERT INTO `questions` VALUES (1939698943747162120, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，普通索引不允许有重复值和空值（NULL）。', '{}', '[[\"false\"]]', '普通索引允许有重复值和空值（NULL），这是MySQL的基本索引类型。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162121, 1939698943482920961, 1939698943482920962, 'judge', 'InnoDB存储引擎不支持事务处理，不具备ACID特性。', '{}', '[[\"false\"]]', 'InnoDB是MySQL的默认存储引擎，支持事务处理，具备原子性（A）、一致性（C）、隔离性（I）和持久性（D）等ACID特性。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162122, 1939698943482920961, 1939698943482920962, 'judge', '视图是一个实际存储数据的表，可以用于数据的插入、更新和删除操作。', '{}', '[[\"false\"]]', '视图是一个虚拟表，不存储数据，但可以通过视图对基表进行插入、更新和删除操作，不过这些操作会受到某些限制。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162123, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，唯一性索引的列值必须是唯一的，不允许有空值。', '{}', '[[\"false\"]]', '唯一性索引的列值必须是唯一的，但允许有空值。主键索引是一种特殊的唯一性索引，不允许有空值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162124, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务不需要满足ACID特性。', '{}', '[[\"false\"]]', '事务必须满足ACID特性，即原子性（Atomicity）、一致性（Consistency）、隔离性（Isolation）和持久性（Durability）。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162125, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，全文索引可以创建在任何数据类型的字段上。', '{}', '[[\"false\"]]', '全文索引只能创建在CHAR、VARCHAR和TEXT类型的字段上，用于提高查询字符串数据的效率。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162126, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的存储过程不能包含多个SQL语句，也不可以有输入参数和输出参数。', '{}', '[[\"false\"]]', '存储过程可以包含多个SQL语句，并且可以有输入参数（IN）、输出参数（OUT）和输入输出参数（INOUT）。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162127, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，触发器不是一种特殊的存储过程，不能在数据插入、更新或删除时自动执行。', '{}', '[[\"false\"]]', '触发器是一种特殊的存储过程，可以在数据插入、更新或删除时自动执行，用于实现数据完整性约束或其他特殊任务。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162128, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，READ UNCOMMITTED是最严格的隔离级别。', '{}', '[[\"false\"]]', 'READ UNCOMMITTED是最低的隔离级别，允许读取未提交的事务数据，可能会导致读脏数据。最严格的隔离级别是SERIALIZABLE。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943747162129, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW  TABLES语句可以查看当前数据库的所有表，但不包括视图。', '{}', '[[\"false\"]]', 'SHOW  TABLES语句可以列出当前数据库的所有表，包括视图。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327937, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的索引不能提高查询效率，也不会占用额外的存储空间。', '{}', '[[\"false\"]]', '索引可以提高查询效率，但会占用额外的存储空间，并且在数据插入、更新和删除时需要维护索引，从而降低操作速度。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327938, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW  CREATE  TABLE语句不能查看表的结构定义。', '{}', '[[\"false\"]]', 'SHOW  CREATE  TABLE语句可以查看表的结构定义，包括表的创建语句和存储引擎等信息。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327939, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的视图不能隐藏数据的逻辑复杂性，也不能简化查询语句。', '{}', '[[\"false\"]]', '视图可以隐藏数据的逻辑复杂性，并简化查询语句，使用户可以更方便地访问数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327940, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW  VARIABLES语句不能查看当前会话的变量值。', '{}', '[[\"false\"]]', 'SHOW  VARIABLES语句可以查看当前会话的变量值，也可以查看全局变量值。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327941, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，READ UNCOMMITTED不允许读取未提交的事务数据。', '{}', '[[\"false\"]]', 'READ UNCOMMITTED是最低的隔离级别，允许读取未提交的事务数据，可能会导致读脏数据。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327942, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW  STATUS语句不能查看服务器的状态信息。', '{}', '[[\"false\"]]', 'SHOW  STATUS语句可以查看服务器的状态信息，包括连接数、运行时间、慢查询次数等。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327943, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的存储过程不能提高代码的重用性，也不能减少网络通信流量。', '{}', '[[\"false\"]]', '存储过程可以提高代码的重用性，并减少网络通信流量，因为存储过程在服务器端执行，减少了客户端和服务器之间的数据传输。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327944, 1939698943482920961, 1939698943482920962, 'judge', '在MySQL中，使用SHOW  ENGINES语句不能查看当前数据库支持的存储引擎及其状态。', '{}', '[[\"false\"]]', 'SHOW  ENGINES语句可以查看当前数据库支持的存储引擎及其状态，包括InnoDB、MyISAM等。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (1939698943772327945, 1939698943482920961, 1939698943482920962, 'judge', 'MySQL中的事务隔离级别中，REPEATABLE READ不能防止不可重复读问题。', '{}', '[[\"false\"]]', 'REPEATABLE READ隔离级别可以防止不可重复读问题，确保在同一个事务中多次读取同一数据时，结果是一致的。', 1, NULL, '2025-06-30 22:54:01', '2025-06-30 22:54:01');
INSERT INTO `questions` VALUES (2004898180901322755, 2004898180901322753, 2004898180901322754, 'single', '驾驶人有下列哪种违法行为一次记6分', '{\"A\": \"使用其他车辆行驶证\", \"B\": \"饮酒后驾驶机动车\", \"C\": \"车速超过规定时速50%以上\", \"D\": \"违法占用应急车道行驶\"}', '[[\"D\"]]', '请仔细阅读交规', 1, NULL, '2025-12-27 20:52:30', '2025-12-27 20:52:30');
